CREATE TABLE t_res (n serial, name text, ok boolean);
GRANT ALL ON t_res TO PUBLIC; GRANT USAGE ON SEQUENCE t_res_n_seq TO PUBLIC;
CREATE FUNCTION chk(p_name text, p_ok boolean) RETURNS void LANGUAGE sql AS $$ INSERT INTO t_res(name, ok) VALUES (p_name, coalesce(p_ok, false)) $$;
CREATE FUNCTION try(p_sql text) RETURNS text LANGUAGE plpgsql AS $$ BEGIN EXECUTE p_sql; RETURN 'OK'; EXCEPTION WHEN OTHERS THEN RETURN SQLSTATE; END $$;
INSERT INTO lb_businesses VALUES ('00000000-0000-0000-0000-0000000000b1','00000000-0000-0000-0000-0000000000a1'),('00000000-0000-0000-0000-0000000000b2','00000000-0000-0000-0000-0000000000a2');
SELECT set_config('test.tenant','00000000-0000-0000-0000-0000000000a1',false), set_config('test.perms','sales.create',false);
SELECT chk('token: cashier refused', try($$ SELECT pos_etims_integration_token('00000000-0000-0000-0000-0000000000b1') $$) = '42501');
SELECT set_config('test.perms','settings.manage',false);
SELECT chk('token: other business refused', try($$ SELECT pos_etims_integration_token('00000000-0000-0000-0000-0000000000b2') $$) = '42501');
CREATE TEMP TABLE k AS SELECT pos_etims_integration_token('00000000-0000-0000-0000-0000000000b1') t1;
SELECT chk('token: 64 random characters', (SELECT length(t1) = 64 AND t1 ~ '^[0-9A-F]+$' FROM k));
SELECT chk('token: asking again returns the SAME token', pos_etims_integration_token('00000000-0000-0000-0000-0000000000b1') = (SELECT t1 FROM k));
SELECT chk('token: rotate gives a NEW one', pos_etims_integration_token('00000000-0000-0000-0000-0000000000b1', true) <> (SELECT t1 FROM k));
SELECT chk('token: still one row per business', (SELECT count(*) FROM lb_etims_integration_tokens) = 1);
SELECT set_config('test.tenant','00000000-0000-0000-0000-0000000000a2',false);
SELECT chk('token: another business gets a different token', pos_etims_integration_token('00000000-0000-0000-0000-0000000000b2') <> (SELECT token FROM lb_etims_integration_tokens WHERE business_id='00000000-0000-0000-0000-0000000000b1'));
SET ROLE authenticated;
SELECT chk('token: browser role cannot read the table', try($$ SELECT * FROM lb_etims_integration_tokens $$) = '42501');
RESET ROLE;
